        /// </remarks>
        /// <exception cref="SMSPool.Client.ApiException">Thrown when fails to make API call</exception>
        /// <param name="service">The service or number retrieved from the &#x60;Service List&#x60; endpoint</param>
        /// <param name="idempotencyKey"> (optional)</param>
        /// <param name="country">The country in ISO format or number retrieved from the &#x60;Country List&#x60; endpoint (optional)</param>
