        /// <param name="pricingOption">Set to 0 if you&#39;d like the cheapest numbers, set to 1 for highest success rate (optional)</param>
        /// <param name="quantity">Quantity of numbers ordered, 1 to 20. Must be a whole number. (optional)</param>
        /// <param name="areacode">Areacodes you would like to include or exclude in JSON format (optional)</param>
        /// <param name="exclude">Set exclude to 1 if you would like to exclude all listed area codes. (optional)</param>
        /// <param name="createToken">Optional param; set to 1 if you&#39;d like to create a token link that anyone can access. (optional)</param>
        /// <param name="activationType">Options: SMS, VOICE, FLASH. SMS will receive regular SMS, VOICE will receive phone calls that mentions the SMS and FLASH is for FLASH calls for verification. (optional)</param>
